1:import { getImage } from 'astro:assets';
2:import { transformUrl, parseUrl } from 'unpic';
3:
4:import type { ImageMetadata } from 'astro';
5:import type { HTMLAttributes } from 'astro/types';
6:
7:type Layout = 'fixed' | 'constrained' | 'fullWidth' | 'cover' | 'responsive' | 'contained';
8:
9:export interface ImageProps extends Omit<HTMLAttributes<'img'>, 'src'> {
10:  src?: string | ImageMetadata | null;
11:  width?: string | number | null;
12:  height?: string | number | null;
13:  alt?: string | null;
14:  loading?: 'eager' | 'lazy' | null;
15:  decoding?: 'sync' | 'async' | 'auto' | null;
16:  style?: string;
17:  srcset?: string | null;
18:  sizes?: string | null;
19:  fetchpriority?: 'high' | 'low' | 'auto' | null;
20:
21:  layout?: Layout;
22:  widths?: number[] | null;
23:  aspectRatio?: string | number | null;
24:  objectPosition?: string;
25:
26:  format?: string;
27:}
28:
29:export type ImagesOptimizer = (
30:  image: ImageMetadata | string,
31:  breakpoints: number[],
32:  width?: number,
33:  height?: number,
34:  format?: string
35:) => Promise<Array<{ src: string; width: number }>>;
36:
37:/* ******* */
38:const config = {
39:  // FIXME: Use this when image.width is minor than deviceSizes
40:  imageSizes: [16, 32, 48, 64, 96, 128, 256, 384],
41:
42:  deviceSizes: [
43:    640, // older and lower-end phones
44:    750, // iPhone 6-8
45:    828, // iPhone XR/11
46:    960, // older horizontal phones
47:    1080, // iPhone 6-8 Plus
48:    1280, // 720p
49:    1668, // Various iPads
50:    1920, // 1080p
51:    2048, // QXGA
52:    2560, // WQXGA
53:    3200, // QHD+
54:    3840, // 4K
55:    4480, // 4.5K
56:    5120, // 5K
57:    6016, // 6K
58:  ],
59:
60:  formats: ['image/webp'],
61:};
62:
63:const computeHeight = (width: number, aspectRatio: number) => {
64:  return Math.floor(width / aspectRatio);
65:};
66:
67:const parseAspectRatio = (aspectRatio: number | string | null | undefined): number | undefined => {
68:  if (typeof aspectRatio === 'number') return aspectRatio;
69:
70:  if (typeof aspectRatio === 'string') {
71:    const match = aspectRatio.match(/(\d+)\s*[/:]\s*(\d+)/);
72:
73:    if (match) {
74:      const [, num, den] = match.map(Number);
75:      if (den && !isNaN(num)) return num / den;
76:    } else {
77:      const numericValue = parseFloat(aspectRatio);
78:      if (!isNaN(numericValue)) return numericValue;
79:    }
80:  }
81:
82:  return undefined;
83:};
84:
85:/**
86: * Gets the `sizes` attribute for an image, based on the layout and width
87: */
88:export const getSizes = (width?: number, layout?: Layout): string | undefined => {
89:  if (!width || !layout) {
90:    return undefined;
91:  }
92:  switch (layout) {
93:    // If screen is wider than the max size, image width is the max size,
94:    // otherwise it's the width of the screen
95:    case `constrained`:
96:      return `(min-width: ${width}px) ${width}px, 100vw`;
97:
98:    // Image is always the same width, whatever the size of the screen
99:    case `fixed`:
100:      return `${width}px`;
101:
102:    // Image is always the width of the screen
103:    case `fullWidth`:
104:      return `100vw`;
105:
106:    default:
107:      return undefined;
108:  }
109:};
110:
111:const pixelate = (value?: number) => (value || value === 0 ? `${value}px` : undefined);
112:
113:const getStyle = ({
114:  width,
115:  height,
116:  aspectRatio,
117:  layout,
118:  objectFit = 'cover',
119:  objectPosition = 'center',
120:  background,
121:}: {
122:  width?: number;
123:  height?: number;
124:  aspectRatio?: number;
125:  objectFit?: string;
126:  objectPosition?: string;
127:  layout?: string;
128:  background?: string;
129:}) => {
130:  const styleEntries: Array<[prop: string, value: string | undefined]> = [
131:    ['object-fit', objectFit],
132:    ['object-position', objectPosition],
133:  ];
134:
135:  // If background is a URL, set it to cover the image and not repeat
136:  if (background?.startsWith('https:') || background?.startsWith('http:') || background?.startsWith('data:')) {
137:    styleEntries.push(['background-image', `url(${background})`]);
138:    styleEntries.push(['background-size', 'cover']);
139:    styleEntries.push(['background-repeat', 'no-repeat']);
140:  } else {
141:    styleEntries.push(['background', background]);
142:  }
143:  if (layout === 'fixed') {
144:    styleEntries.push(['width', pixelate(width)]);
145:    styleEntries.push(['height', pixelate(height)]);
146:    styleEntries.push(['object-position', 'top left']);
147:  }
148:  if (layout === 'constrained') {
149:    styleEntries.push(['max-width', pixelate(width)]);
150:    styleEntries.push(['max-height', pixelate(height)]);
151:    styleEntries.push(['aspect-ratio', aspectRatio ? `${aspectRatio}` : undefined]);
152:    styleEntries.push(['width', '100%']);
153:  }
154:  if (layout === 'fullWidth') {
155:    styleEntries.push(['width', '100%']);
156:    styleEntries.push(['aspect-ratio', aspectRatio ? `${aspectRatio}` : undefined]);
157:    styleEntries.push(['height', pixelate(height)]);
158:  }
159:  if (layout === 'responsive') {
160:    styleEntries.push(['width', '100%']);
161:    styleEntries.push(['height', 'auto']);
162:    styleEntries.push(['aspect-ratio', aspectRatio ? `${aspectRatio}` : undefined]);
163:  }
164:  if (layout === 'contained') {
165:    styleEntries.push(['max-width', '100%']);
166:    styleEntries.push(['max-height', '100%']);
167:    styleEntries.push(['object-fit', 'contain']);
168:    styleEntries.push(['aspect-ratio', aspectRatio ? `${aspectRatio}` : undefined]);
169:  }
170:  if (layout === 'cover') {
171:    styleEntries.push(['max-width', '100%']);
172:    styleEntries.push(['max-height', '100%']);
173:  }
174:
175:  const styles = Object.fromEntries(styleEntries.filter(([, value]) => value));
176:
177:  return Object.entries(styles)
178:    .map(([key, value]) => `${key}: ${value};`)
179:    .join(' ');
180:};
181:
182:const getBreakpoints = ({
183:  width,
184:  breakpoints,
185:  layout,
186:}: {
187:  width?: number;
188:  breakpoints?: number[];
189:  layout: Layout;
190:}): number[] => {
191:  if (layout === 'fullWidth' || layout === 'cover' || layout === 'responsive' || layout === 'contained') {
192:    return breakpoints || config.deviceSizes;
193:  }
194:  if (!width) {
195:    return [];
196:  }
197:  const doubleWidth = width * 2;
198:  if (layout === 'fixed') {
199:    return [width, doubleWidth];
200:  }
201:  if (layout === 'constrained') {
202:    return [
203:      // Always include the image at 1x and 2x the specified width
204:      width,
205:      doubleWidth,
206:      // Filter out any resolutions that are larger than the double-res image
207:      ...(breakpoints || config.deviceSizes).filter((w) => w < doubleWidth),
208:    ];
209:  }
210:
211:  return [];
212:};
213:
214:/* ** */
215:export const astroAssetsOptimizer: ImagesOptimizer = async (
216:  image,
217:  breakpoints,
218:  _width,
219:  _height,
220:  format = undefined
221:) => {
222:  if (!image) {
223:    return [];
224:  }
225:
226:  return Promise.all(
227:    breakpoints.map(async (w: number) => {
228:      const result = await getImage({ src: image, width: w, inferSize: true, ...(format ? { format: format } : {}) });
229:
230:      return {
231:        src: result?.src,
232:        width: result?.attributes?.width ?? w,
233:        height: result?.attributes?.height,
234:      };
235:    })
236:  );
237:};
238:
239:export const isUnpicCompatible = (image: string) => {
240:  return typeof parseUrl(image) !== 'undefined';
241:};
242:
243:/* ** */
244:export const unpicOptimizer: ImagesOptimizer = async (image, breakpoints, width, height, format = undefined) => {
245:  if (!image || typeof image !== 'string') {
246:    return [];
247:  }
248:
249:  const urlParsed = parseUrl(image);
250:  if (!urlParsed) {
251:    return [];
252:  }
253:
254:  return Promise.all(
255:    breakpoints.map(async (w: number) => {
256:      const _height = width && height ? computeHeight(w, width / height) : height;
257:      const url =
258:        transformUrl({
259:          url: image,
260:          width: w,
261:          height: _height,
262:          cdn: urlParsed.cdn,
263:          ...(format ? { format: format } : {}),
264:        }) || image;
265:      return {
266:        src: String(url),
267:        width: w,
268:        height: _height,
269:      };
270:    })
271:  );
272:};
273:
274:/* ** */
275:export async function getImagesOptimized(
276:  image: ImageMetadata | string,
277:  {
278:    src: _,
279:    width,
280:    height,
281:    sizes,
282:    aspectRatio,
283:    objectPosition,
284:    widths,
285:    layout = 'constrained',
286:    style = '',
287:    format,
288:    ...rest
289:  }: ImageProps,
290:  transform: ImagesOptimizer = () => Promise.resolve([])
291:): Promise<{ src: string; attributes: HTMLAttributes<'img'> }> {
292:  if (typeof image !== 'string') {
293:    width ||= Number(image.width) || undefined;
294:    height ||= typeof width === 'number' ? computeHeight(width, image.width / image.height) : undefined;
295:  }
296:
297:  width = (width && Number(width)) || undefined;
298:  height = (height && Number(height)) || undefined;
299:
300:  widths ||= config.deviceSizes;
301:  sizes ||= getSizes(Number(width) || undefined, layout);
302:  aspectRatio = parseAspectRatio(aspectRatio);
303:
304:  // Calculate dimensions from aspect ratio
305:  if (aspectRatio) {
306:    if (width) {
307:      if (height) {
308:        /* empty */
309:      } else {
310:        height = width / aspectRatio;
311:      }
312:    } else if (height) {
313:      width = Number(height * aspectRatio);
314:    } else if (layout !== 'fullWidth') {
315:      // Fullwidth images have 100% width, so aspectRatio is applicable
316:      console.error('When aspectRatio is set, either width or height must also be set');
317:      console.error('Image', image);
318:    }
319:  } else if (width && height) {
320:    aspectRatio = width / height;
321:  } else if (layout !== 'fullWidth') {
322:    // Fullwidth images don't need dimensions
323:    console.error('Either aspectRatio or both width and height must be set');
324:    console.error('Image', image);
325:  }
326:
327:  let breakpoints = getBreakpoints({ width: width, breakpoints: widths, layout: layout });
328:  breakpoints = [...new Set(breakpoints)].sort((a, b) => a - b);
329:
330:  const srcset = (await transform(image, breakpoints, Number(width) || undefined, Number(height) || undefined, format))
331:    .map(({ src, width }) => `${src} ${width}w`)
332:    .join(', ');
333:
334:  return {
335:    src: typeof image === 'string' ? image : image.src,
336:    attributes: {
337:      width: width,
338:      height: height,
339:      srcset: srcset || undefined,
340:      sizes: sizes,
341:      style: `${getStyle({
342:        width: width,
343:        height: height,
344:        aspectRatio: aspectRatio,
345:        objectPosition: objectPosition,
346:        layout: layout,
347:      })}${style ?? ''}`,
348:      ...rest,
349:    },
350:  };
351:}

