import { describe, it, expect } from 'vitest';
import { getBreakpoints } from './images-optimization';

const imageSizes = [16, 32, 48, 64, 96, 128, 256, 384];
const smallestDeviceSize = 640;

describe('getBreakpoints — imageSizes vs deviceSizes selection', () => {
  describe('when image is narrower than smallest deviceSize', () => {
    it('uses imageSizes for fullWidth layout with a narrow image', () => {
      const result = getBreakpoints({
        layout: 'fullWidth',
        imageWidth: 300,
      });
      // Should only contain entries from imageSizes that are <= 300
      expect(result.every((bp) => bp <= 300)).toBe(true);
      expect(result).toEqual(imageSizes.filter((s) => s <= 300));
    });

    it('uses imageSizes for responsive layout with a narrow image', () => {
      const result = getBreakpoints({
        layout: 'responsive',
        imageWidth: 200,
      });
      expect(result.every((bp) => bp <= 200)).toBe(true);
      expect(result).toEqual(imageSizes.filter((s) => s <= 200));
    });

    it('uses imageSizes for constrained layout with a narrow image', () => {
      const result = getBreakpoints({
        width: 100,
        layout: 'constrained',
        imageWidth: 100,
      });
      // Should include width, doubleWidth, plus imageSizes entries < doubleWidth
      const doubleWidth = 200;
      const expected = [100, doubleWidth, ...imageSizes.filter((s) => s < doubleWidth)];
      expect(result).toEqual(expected);
      // None of the fallback sizes should come from deviceSizes
      expect(result.every((bp) => bp < smallestDeviceSize)).toBe(true);
    });

    it('filters imageSizes to those <= imageWidth for cover layout', () => {
      const result = getBreakpoints({
        layout: 'cover',
        imageWidth: 64,
      });
      expect(result).toEqual([16, 32, 48, 64]);
    });
  });

  describe('when image is wider than smallest deviceSize', () => {
    it('still uses deviceSizes for fullWidth layout', () => {
      const result = getBreakpoints({
        layout: 'fullWidth',
        imageWidth: 1200,
      });
      // Should be full deviceSizes array (no filtering by imageWidth)
      expect(result.some((bp) => bp >= smallestDeviceSize)).toBe(true);
    });

    it('still uses deviceSizes for constrained layout', () => {
      const result = getBreakpoints({
        width: 800,
        layout: 'constrained',
        imageWidth: 900,
      });
      // Should include deviceSizes entries
      expect(result.some((bp) => bp >= smallestDeviceSize)).toBe(true);
    });
  });

  describe('when imageWidth is not provided', () => {
    it('falls back to deviceSizes as before for fullWidth', () => {
      const result = getBreakpoints({
        layout: 'fullWidth',
      });
      expect(result[0]).toBe(smallestDeviceSize);
    });

    it('falls back to deviceSizes for constrained', () => {
      const result = getBreakpoints({
        width: 400,
        layout: 'constrained',
      });
      // Should include deviceSizes entries < doubleWidth
      expect(result).toContain(400);
      expect(result).toContain(800);
      expect(result).toContain(640);
      expect(result).toContain(750);
    });
  });

  describe('custom breakpoints always take precedence', () => {
    it('uses custom breakpoints even for a narrow image', () => {
      const custom = [100, 200, 500];
      const result = getBreakpoints({
        layout: 'fullWidth',
        breakpoints: custom,
        imageWidth: 300,
      });
      expect(result).toEqual(custom);
    });
  });

  describe('fixed layout is unaffected', () => {
    it('returns [width, 2x] regardless of imageWidth', () => {
      const result = getBreakpoints({
        width: 50,
        layout: 'fixed',
        imageWidth: 50,
      });
      expect(result).toEqual([50, 100]);
    });
  });
});


